module rffe_register(
  input  logic clk,
  input  logic rst_n,
  input  logic sclk,
  input  logic sdata,
  output logic sdata_out,
  output logic sdata_oe
);

  logic sclk_ff, sdata_ff;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      sclk_ff  <= 1'b0;
      sdata_ff <= 1'b0;
    end else begin
      sclk_ff  <= sclk;
      sdata_ff <= sdata;
    end
  end

  wire sclk_rise = (sclk & ~sclk_ff);
  wire sclk_fall = (~sclk & sclk_ff);
  wire sdata_r   = sdata_ff;

  localparam [3:0] IDLE=0, USID=1, CMD=2, CPAR=3, WDATA=4, WPAR=5,
                   RPARK=6, RDATA=7, RPAR=8, RBPARK=9;

  logic [3:0] state;
  logic [3:0] bitcnt;
  logic [7:0] cmd_sh;
  logic [7:0] wdata_sh;
  logic [7:0] regs [0:15];
  integer i;
  logic [7:0] rd_data;
  reg sdata_out_r;
  reg sdata_oe_r;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state       <= IDLE;
      bitcnt      <= 4'd0;
      cmd_sh      <= 8'd0;
      wdata_sh    <= 8'd0;
      rd_data     <= 8'd0;
      sdata_out_r <= 1'b0;
      sdata_oe_r  <= 1'b0;
      for (i = 0; i < 16; i = i + 1) regs[i] <= 8'hFF;
    end else begin
      case (state)
        IDLE: begin
          sdata_oe_r  <= 1'b0;
          sdata_out_r <= 1'b0;
          if (sclk_rise && sdata_r) begin
            state  <= USID;
            bitcnt <= 4'd0;
          end
        end

        USID: begin
          if (sclk_rise) begin
            if (bitcnt == 4'd3) begin
              state  <= CMD;
              bitcnt <= 4'd0;
              cmd_sh <= 8'd0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        CMD: begin
          if (sclk_rise) begin
            cmd_sh <= {cmd_sh[6:0], sdata_r};
            if (bitcnt == 4'd7) begin
              state  <= CPAR;
              bitcnt <= 4'd0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        CPAR: begin
          if (sclk_rise) begin
            if (cmd_sh[7:5] == 3'b010) begin
              state    <= WDATA;
              bitcnt   <= 4'd0;
              wdata_sh <= 8'd0;
            end else if (cmd_sh[7:5] == 3'b011) begin
              state  <= RPARK;
              bitcnt <= 4'd0;
            end else begin
              state <= IDLE;
            end
          end
        end

        WDATA: begin
          if (sclk_rise) begin
            wdata_sh <= {wdata_sh[6:0], sdata_r};
            if (bitcnt == 4'd7) begin
              state  <= WPAR;
              bitcnt <= 4'd0;
            end else begin
              bitcnt <= bitcnt + 4'd1;
            end
          end
        end

        WPAR: begin
          if (sclk_rise) begin
            if (cmd_sh[4:0] <= 5'd15) begin
              regs[cmd_sh[3:0]] <= regs[cmd_sh[3:0]] & ~wdata_sh;
            end
            state  <= IDLE;
            bitcnt <= 4'd0;
          end
        end

        RPARK: begin
          if (sclk_rise) begin
            if (cmd_sh[4:0] <= 5'd15) begin
              rd_data     <= regs[cmd_sh[3:0]];
              sdata_out_r <= regs[cmd_sh[3:0]][7];
              sdata_oe_r  <= 1'b1;
            end
            state  <= RDATA;
            bitcnt <= 4'd0;
          end
        end

        RDATA: begin
          if (sclk_fall) begin
            if (bitcnt == 4'd7) begin
              sdata_out_r <= ~(^rd_data);
              state       <= RPAR;
            end else begin
              sdata_out_r <= rd_data[6 - bitcnt];
              bitcnt      <= bitcnt + 4'd1;
            end
          end
        end

        RPAR: begin
          if (sclk_fall) begin
            sdata_out_r <= 1'b0;
            state       <= RBPARK;
          end
        end

        RBPARK: begin
          if (sclk_fall) begin
            sdata_oe_r <= 1'b0;
            state      <= IDLE;
          end
        end

        default: state <= IDLE;
      endcase
    end
  end

  assign sdata_out = sdata_out_r;
  assign sdata_oe  = sdata_oe_r;

endmodule
